// Fixture generated by upstream 0.5.0 and the local fork; see doc/components.md#upstream-attribution.
use super::support::Database;
use cqrsx::cqrs::{
    CqrsFramework,
    aggregate::Aggregate,
    command::decide::Decide,
    event::DomainEvent,
    store::{EventStore, persisted::PersistedEventStore, repository::PersistedEventRepository},
};
use cqrsx::postgres::event_repository::PostgresEventRepository;
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};
use sqlx::Row;
use std::collections::HashMap;

#[derive(Clone, Default, Debug, Serialize, Deserialize)]
pub struct State {
    pub value: i64,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub enum Event {
    ValueSet { value: i64 },
}

impl DomainEvent for Event {
    fn event_type(&self) -> String {
        "ValueSet".into()
    }
    fn event_version(&self) -> String {
        "1".into()
    }
}

impl Aggregate for State {
    const TYPE: &'static str = "framework_compatibility_v0_5";
    type Id = String;
    type Command = i64;
    type Event = Event;
    type Error = std::convert::Infallible;
    type Rules = ();
    fn apply(&mut self, event: Event) {
        let Event::ValueSet { value } = event;
        self.value = value;
    }
}
impl Decide<State> for i64 {
    fn decide(self, _: &State, _: &()) -> Result<Event, std::convert::Infallible> {
        Ok(Event::ValueSet { value: self })
    }
}

#[tokio::test]
async fn upstream_data_preserves_formats_snapshot_tail_and_next_sequence() {
    let fixture: Value = serde_json::from_str(include_str!("fixtures/framework_v0_5.json")).unwrap();
    let db = Database::new().await;
    for event in fixture["events"].as_array().unwrap() {
        sqlx::query("INSERT INTO events (aggregate_type, aggregate_id, sequence, event_type, event_version, payload, metadata) VALUES ($1,$2,$3,$4,$5,$6,$7)")
            .bind(event["aggregate_type"].as_str().unwrap())
            .bind(event["aggregate_id"].as_str().unwrap())
            .bind(event["sequence"].as_i64().unwrap())
            .bind(event["event_type"].as_str().unwrap())
            .bind(event["event_version"].as_str().unwrap())
            .bind(&event["payload"]).bind(&event["metadata"])
            .execute(&db.pool).await.unwrap();
    }
    for snapshot in fixture["snapshots"].as_array().unwrap() {
        sqlx::query("INSERT INTO snapshots (aggregate_type, aggregate_id, last_sequence, current_snapshot, payload) VALUES ($1,$2,$3,$4,$5)")
            .bind(snapshot["aggregate_type"].as_str().unwrap())
            .bind(snapshot["aggregate_id"].as_str().unwrap())
            .bind(snapshot["last_sequence"].as_i64().unwrap())
            .bind(snapshot["current_snapshot"].as_i64().unwrap())
            .bind(&snapshot["payload"]).execute(&db.pool).await.unwrap();
    }
    for (id, value, sequence, snapshot) in [("old", 30, 3, 1), ("shared", 40, 4, 2), ("local", 7, 3, 1)] {
        let repository = PostgresEventRepository::new(db.pool.clone());
        let stored = repository.events::<State>(id).await.unwrap();
        for event in stored {
            let found = json!({"aggregate_type":event.aggregate_type,"aggregate_id":event.aggregate_id,"sequence":event.sequence,"event_type":event.event_type,"event_version":event.event_version,"payload":event.payload,"metadata":event.metadata});
            let expected = fixture["events"]
                .as_array()
                .unwrap()
                .iter()
                .find(|e| e["aggregate_id"] == id && e["sequence"] == found["sequence"])
                .unwrap();
            assert_eq!(&found, expected);
        }
        let store = PersistedEventStore::<_, State>::new(repository).with_snapshots(std::num::NonZeroUsize::new(2).unwrap());
        let context = store.load_aggregate(id).await.unwrap();
        assert_eq!(context.aggregate.value, value);
        assert_eq!(context.current_sequence, sequence);
        assert_eq!(context.snapshot_version, Some(snapshot));
        assert_eq!(store.load_events(id).await.unwrap().len(), sequence);
        let events_only = PersistedEventStore::<_, State>::new(PostgresEventRepository::new(db.pool.clone()));
        assert_eq!(events_only.load_aggregate(id).await.unwrap().aggregate.value, value);
    }
    let store = PersistedEventStore::<_, State>::new(PostgresEventRepository::new(db.pool.clone()))
        .with_snapshots(std::num::NonZeroUsize::new(2).unwrap());
    let framework = CqrsFramework::new(store, ());
    framework
        .execute_with_metadata(
            &"old".into(),
            50,
            HashMap::from([("correlation_id".into(), "after-fork".into())]),
        )
        .await
        .unwrap();
    let row = sqlx::query("SELECT * FROM events WHERE aggregate_id = 'old' AND sequence = 4")
        .fetch_one(&db.pool)
        .await
        .unwrap();
    assert_eq!(row.get::<String, _>("aggregate_type"), State::TYPE);
    assert_eq!(row.get::<String, _>("event_type"), "ValueSet");
    assert_eq!(row.get::<String, _>("event_version"), "1");
    assert_eq!(row.get::<Value, _>("payload"), json!({"ValueSet":{"value":50}}));
    assert_eq!(row.get::<Value, _>("metadata"), json!({"correlation_id":"after-fork"}));
    let store = PersistedEventStore::<_, State>::new(PostgresEventRepository::new(db.pool.clone()))
        .with_snapshots(std::num::NonZeroUsize::new(2).unwrap());
    let context = store.load_aggregate("old").await.unwrap();
    assert_eq!(context.aggregate.value, 50);
    assert_eq!(context.current_sequence, 4);
    assert_eq!(context.snapshot_version, Some(2));
    db.close().await;
}
